let dashboardBusy=false;
async function pollDashboard(){
 if(dashboardBusy || !state.session?.user || modal.open || document.hidden)return;
 if(state.page!=='dashboard' && state.page!=='points')return;
 dashboardBusy=true;
 try{
  const dashboard=await api('/api/dashboard');
  if(!modal.open){
   state.dashboard=dashboard;state.points=dashboard.points;
   if(state.page==='dashboard')renderDashboard();
   else if(document.activeElement?.id!=='point-search')renderPoints();
   const indicator=$('.connection-label');if(indicator)indicator.innerHTML='<i class="status-dot"></i>Servidor local';
  }
 }catch{const indicator=$('.connection-label');if(indicator)indicator.textContent='Sem conexão — tentando novamente';}
 finally{dashboardBusy=false;}
}
